1	export { validateSpec, extractGateSection } from './gate/validate.js';
2	export { renderText, renderJson } from './gate/report.js';
3	export { draftGateSection, smartReview } from './pipeline/agent.js';
4	export {
5	  GATE_CHECKS,
6	  GATE_HEADING,
7	  RISK_TIERS,
8	  verdictFrom,
9	  type Finding,
10	  type GateCheck,
11	  type GateResult,
12	  type RiskTier,
13	  type Severity,
14	  type Verdict
15	} from './gate/schema.js';
16

1	import { query } from '@anthropic-ai/claude-agent-sdk';
2	import { Finding } from '../gate/schema.js';
3	
4	const DEFAULT_MODEL = process.env.FRAI_GATE_MODEL ?? 'claude-opus-5';
5	
6	const SECRETS_GUARD = `Never read, quote, or summarize secret material: skip .env and .env.* files, private keys and certificates (id_*, *.pem, *.key, *.p12), credential stores, token caches, and anything under a secrets/ or credentials/ directory. If a gate answer would require their contents, write "NEEDS HUMAN INPUT" instead.`;
7	
8	const READ_ONLY_OPTIONS = {
9	  allowedTools: ['Read', 'Glob', 'Grep'],
10	  disallowedTools: ['Write', 'Edit', 'NotebookEdit', 'Bash', 'WebFetch', 'WebSearch', 'Task'],
11	  permissionMode: 'bypassPermissions' as const,
12	  model: DEFAULT_MODEL
13	};
14	
15	async function runQuery(prompt: string, cwd: string, maxTurns: number): Promise<string> {
16	  const stream = query({
17	    prompt,
18	    options: { ...READ_ONLY_OPTIONS, cwd, maxTurns }
19	  });
20	
21	  let resultText = '';
22	  for await (const message of stream) {
23	    const anyMessage = message as { type?: string; subtype?: string; result?: string };
24	    if (anyMessage.type === 'result') {
25	      if (anyMessage.subtype && anyMessage.subtype !== 'success') {
26	        throw new Error(`Agent run ended without success (${anyMessage.subtype}).`);
27	      }
28	      resultText = anyMessage.result ?? '';
29	    }
30	  }
31	  return resultText;
32	}
33	
34	function between(text: string, begin: string, end: string): string | null {
35	  const start = text.indexOf(begin);
36	  if (start === -1) return null;
37	  const stop = text.indexOf(end, start + begin.length);
38	  if (stop === -1) return null;
39	  return text.slice(start + begin.length, stop).trim();
40	}
41	
42	/**
43	 * Scans the repository at `cwd` with a read-only Claude Agent SDK session and drafts
44	 * a filled-in "## Responsible AI Gate" section grounded in the actual code.
45	 */
46	export async function draftGateSection(cwd: string): Promise<string> {
47	  const prompt = `You are FRAI's Responsible AI Gate drafter. Explore this repository (read-only: Read, Glob, Grep) and identify how AI is used: model/API calls (OpenAI, Anthropic, HuggingFace, local models), training or fine-tuning code, prompts, user data flowing into models, and AI output shown to users.
48	
49	${SECRETS_GUARD}
50	
51	Then draft a completed "## Responsible AI Gate" spec section with these seven subsections:
52	### Risk tier            - tier (prohibited/high/limited/minimal) + justification + sign-off line
53	### Data provenance & privacy - sources, PII yes/no + basis, retention, trained-on-user-data
54	### Human oversight      - automation level, override path, kill switch
55	### Evaluation plan      - metrics with numeric thresholds, eval dataset, owner/when
56	### Bias & fairness      - groups at risk, mitigations, test method
57	### Monitoring & rollback - signals, numeric degradation definition, rollback trigger/procedure
58	### Transparency & incident response - user disclosure, incident owner, response path
59	
60	Rules:
61	- Ground every answer in what you actually found in the code; cite file paths inline where useful.
62	- Where an answer requires a human/business decision you cannot infer (retention policy, sign-off, incident owner), write "NEEDS HUMAN INPUT: <specific question>" instead of inventing a value.
63	- Propose concrete numeric thresholds as suggestions where the code implies them (mark them "suggested").
64	- If the repo contains no AI usage at all, say so plainly instead of drafting a gate.
65	
66	Output ONLY the drafted markdown between these exact markers:
67	<!-- RAI-GATE:BEGIN -->
68	## Responsible AI Gate
69	...subsections...
70	<!-- RAI-GATE:END -->`;
71	
72	  const result = await runQuery(prompt, cwd, 50);
73	  const section = between(result, '<!-- RAI-GATE:BEGIN -->', '<!-- RAI-GATE:END -->');
74	  if (section) return section;
75	  if (/## Responsible AI Gate/i.test(result)) return result.trim();
76	  throw new Error(`Agent did not return a gate section. Raw output:\n${result}`);
77	}
78	
79	/**
